int main(){int seen[8192]={}; for(int rank=0;rank<8;++rank){for(int block=0;block<2048;++block){int tile0=-1;for(int thread=0;thread<128;thread+=32){int group=(block / 32) * 128 + block % 32 + (thread / 32) * 32;if(group<0||group>=8192)return 1; if(rank==0)++seen[group];int tile=(rank*2+(group/32)/128)*32+group%32;if(tile0<0)tile0=tile;else if(tile!=tile0)return 2;}}}for(int group=0;group<8192;++group)if(seen[group]!=1)return 3;return 0;}